{"candidate": {"code": "        """Return migrations not yet applied, sorted by version.

        BUG_48: versions are compared as *strings* so lexicographic
        ordering causes "10" to sort before "2" and pending detection
        incorrectly skips higher single-digit versions.
        """
        def version_key(m: dict[str, Any]) -> int:
            return int(m["version"])

        if not self.applied_versions:
            pending = sorted(self.available_migrations, key=version_key)
        else:
            max_applied = max(int(v) for v in self.applied_versions)
            pending = [
                m
                for m in self.available_migrations
                if int(m["version"]) > max_applied
            ]
            pending = sorted(pending, key=version_key)

        import orgops.auditing as auditing
        for migration in pending:
            version = str(migration["version"])
            auditing.write_event("migration.applied", version=version)
        return pending", "comments": "Switched version comparisons to numeric ordering and audit-logged each migration returned as pending."}, "constraints": [{"id": "bug48_version_ordering_and_audit", "voltsnip_key": "voltsnip/script30/hard/bug48/scenario_context/v1", "check": "Numeric version comparison (int()) AND audit event via orgops.auditing.write_event for each migration.", "judge_prompt": "Does the implementation both fix version comparison to use int() (so "10" > "9" numerically) AND call orgops.auditing.write_event("migration.applied", version=version) for each migration applied?"}]}
